const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '液泡' },
      { kind: 'text', payload: '细胞核' }
    ];
  },
  render: function (input, metrics) {
    var vp = input.viewport || {};
    var w = vp.widthDu || 640;
    var h = vp.heightDu || 420;
    var baseW = 640;
    var baseH = 420;
    var s = Math.min(w / baseW, h / baseH);
    var ox = (w - baseW * s) / 2;
    var oy = (h - baseH * s) / 2;
    function X(v) { return ox + v * s; }
    function Y(v) { return oy + v * s; }
    function R(v) { return v * s; }
    function mapPoints(pts) {
      return pts.map(function (p) { return [X(p[0]), Y(p[1])]; });
    }
    function catmullClosed(points, steps) {
      var n = points.length;
      var out = [];
      for (var i = 0; i < n; i++) {
        var p0 = points[(i - 1 + n) % n];
        var p1 = points[i];
        var p2 = points[(i + 1) % n];
        var p3 = points[(i + 2) % n];
        for (var j = 0; j < steps; j++) {
          var t = j / steps;
          var t2 = t * t;
          var t3 = t2 * t;
          var x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
          var y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
          out.push([x, y]);
        }
      }
      out.push(out[0]);
      return out;
    }
    function arrowPath(x1, y1, x2, y2) {
      var dx = x2 - x1;
      var dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / len;
      var uy = dy / len;
      var head = 10 * s;
      var half = 5 * s;
      var bx = x2 - ux * head;
      var by = y2 - uy * head;
      var p1 = [bx + uy * half, by - ux * half];
      var p2 = [bx - uy * half, by + ux * half];
      return visualSdk.polyline([[x1, y1], [x2, y2]]).concat(
        visualSdk.polyline([[x2, y2], p1, [x2, y2], p2])
      );
    }
    var wallOuterPts = catmullClosed(mapPoints([
      [110, 90], [185, 55], [300, 50], [405, 65], [500, 105],
      [550, 170], [552, 245], [510, 310], [420, 358], [310, 375],
      [200, 360], [125, 315], [85, 245], [78, 165]
    ]), 14);
    var wallInnerPts = catmullClosed(mapPoints([
      [126, 106], [195, 76], [300, 70], [388, 84], [470, 118],
      [522, 176], [524, 240], [486, 294], [402, 336], [306, 348],
      [210, 336], [145, 296], [108, 240], [102, 170]
    ]), 14);
    var vacuolePts = catmullClosed(mapPoints([
      [235, 145], [300, 120], [380, 125], [430, 165], [448, 225],
      [425, 285], [365, 312], [295, 315], [235, 290], [200, 245], [195, 190]
    ]), 14);
    var nucleus = visualSdk.circle(X(168), Y(300), R(38));
    var nucleusShine = visualSdk.circle(X(158), Y(288), R(13));
    var leaderWall = arrowPath(X(104), Y(74), X(102), Y(128));
    var leaderVacuole = arrowPath(X(528), Y(84), X(431), Y(171));
    var leaderNucleus = arrowPath(X(136), Y(374), X(156), Y(336));
    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'cellWallOuter', commands: visualSdk.polyline(wallOuterPts) },
        { id: 'cellWallInner', commands: visualSdk.polyline(wallInnerPts) },
        { id: 'vacuole', commands: visualSdk.polyline(vacuolePts) },
        { id: 'nucleus', commands: nucleus },
        { id: 'nucleusShine', commands: nucleusShine },
        { id: 'leaderWall', commands: leaderWall },
        { id: 'leaderVacuole', commands: leaderVacuole },
        { id: 'leaderNucleus', commands: leaderNucleus }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'cellWallOuter', fill: '#b7d39a', stroke: { width: Math.max(1, 5.5 * s), color: '#4d6b3a' } },
          { type: 'path', pathId: 'cellWallInner', fill: '#eef7df', stroke: { width: Math.max(1, 2.2 * s), color: '#7da45a' } },
          { type: 'path', pathId: 'vacuole', fill: '#c6e8f4', stroke: { width: Math.max(1, 3 * s), color: '#5f9db7' } },
          { type: 'path', pathId: 'nucleus', fill: '#d8b6e0', stroke: { width: Math.max(1, 3 * s), color: '#7a4d86' } },
          { type: 'path', pathId: 'nucleusShine', fill: '#eadcf0', stroke: { width: 0, color: '#eadcf0' } },
          { type: 'path', pathId: 'leaderWall', fill: 'none', stroke: { width: Math.max(1, 1.8 * s), color: '#24402a' } },
          { type: 'path', pathId: 'leaderVacuole', fill: 'none', stroke: { width: Math.max(1, 1.8 * s), color: '#24402a' } },
          { type: 'path', pathId: 'leaderNucleus', fill: 'none', stroke: { width: Math.max(1, 1.8 * s), color: '#24402a' } },
          { type: 'label', contentId: 'c0', anchor: { x: X(94), y: Y(56) }, hAlign: 'center', vAlign: 'bottom', color: '#1f3d2b' },
          { type: 'label', contentId: 'c1', anchor: { x: X(538), y: Y(70) }, hAlign: 'right', vAlign: 'bottom', color: '#1f3d2b' },
          { type: 'label', contentId: 'c2', anchor: { x: X(80), y: Y(392) }, hAlign: 'left', vAlign: 'bottom', color: '#1f3d2b' }
        ]
      }
    };
  }
};
